/**
 * Sign-in links (spec §2.1), generated by the app and mailed through Resend
 * instead of Supabase's mailer: the Korean template lives in code and no
 * dashboard SMTP/template setup is needed.
 *
 * The mail links to /auth/confirm, a page with one button. Only that button
 * (a POST) uses the one-time token, so mail scanners that open links ahead of
 * the user can't burn it (CLAUDE.md rule 8).
 */
import { createHmac, randomBytes } from "node:crypto";
import { render } from "@react-email/components";
import type { ServiceClient } from "./supabase/service";
import LoginLink, { loginLinkSubject } from "../emails/LoginLink";
import AccountCode, { accountCodeSubject } from "../emails/AccountCode";
import { BRAND } from "./brand";
import { mailAssets } from "../emails/theme";
import type { OutgoingEmail } from "./email/send";

export type ThrottleVerdict = "ok" | "too_soon" | "too_many";

/** Keyed hash so the throttle table never holds a raw email or IP. */
export function throttleHash(value: string, secret: string): string {
  return createHmac("sha256", secret).update(value.trim().toLowerCase()).digest("hex").slice(0, 40);
}

export async function claimLoginLink(db: ServiceClient, email: string, ip: string | null, secret: string): Promise<ThrottleVerdict> {
  const { data, error } = await db.rpc("claim_login_link", {
    p_email_hash: throttleHash(email, secret),
    p_ip_hash: ip ? throttleHash(ip, secret) : null,
  });
  if (error) throw new Error(`claim_login_link: ${error.message}`);
  return data === "too_soon" || data === "too_many" ? data : "ok";
}

export type LoginToken = { tokenHash: string; type: "magiclink" | "signup" };

/**
 * One-time token for this email. Existing users get a magic link; a new
 * address gets a sign-up confirmation (which also signs them in), so the
 * first click doubles as the email opt-in.
 */
export async function generateLoginToken(db: ServiceClient, email: string): Promise<LoginToken> {
  const magic = await db.auth.admin.generateLink({ type: "magiclink", email });
  if (!magic.error && magic.data.properties?.hashed_token) {
    return { tokenHash: magic.data.properties.hashed_token, type: "magiclink" };
  }
  // No such user yet (or not confirmed yet): a sign-up link creates/confirms them. The password
  // is random and never used — sign-in is always by email link.
  const signup = await db.auth.admin.generateLink({ type: "signup", email, password: randomBytes(32).toString("base64url") });
  if (signup.error || !signup.data.properties?.hashed_token) {
    throw new Error(`generateLink failed: ${magic.error?.code ?? magic.error?.message} / ${signup.error?.code ?? signup.error?.message}`);
  }
  return { tokenHash: signup.data.properties.hashed_token, type: "signup" };
}

export function confirmUrl(appUrl: string, token: LoginToken, next: string): string {
  const q = new URLSearchParams({ token_hash: token.tokenHash, type: token.type, next });
  return `${appUrl}/auth/confirm?${q.toString()}`;
}

export async function composeLoginEmail(input: { email: string; url: string; appUrl: string; idempotencyKey: string }): Promise<OutgoingEmail> {
  const element = (
    <LoginLink
      confirmUrl={input.url}
      logoUrl={mailAssets(input.appUrl).wordmarkUrl}
      banners={{ dawn: mailAssets(input.appUrl).dawnUrl, golden: mailAssets(input.appUrl).goldenUrl, blueHour: mailAssets(input.appUrl).blueHourUrl }}
      fontUrl={mailAssets(input.appUrl).fontUrl}
      brand={BRAND.name}
    />
  );
  return {
    to: input.email,
    subject: loginLinkSubject(BRAND.name),
    html: await render(element),
    text: await render(element, { plainText: true }),
    headers: {},
    idempotencyKey: input.idempotencyKey,
  };
}

/**
 * Six-digit code for 내 정보 on any device (2026-11-14): typed into the page,
 * so nothing has to be clicked in the mail. Only for an existing subscriber —
 * no account is created here; null when there is none (the page answers the
 * same either way, so it can't be used to test addresses).
 */
export async function generateAccountCode(db: ServiceClient, email: string): Promise<string | null> {
  const { data: profile, error } = await db.from("profiles").select("user_id").eq("email", email).maybeSingle();
  if (error) throw new Error(`load profile: ${error.message}`);
  if (!profile) return null;
  const magic = await db.auth.admin.generateLink({ type: "magiclink", email });
  if (magic.error) throw new Error(`generateLink failed: ${magic.error.code ?? magic.error.message}`);
  return magic.data.properties?.email_otp ?? null;
}

export async function composeAccountCodeEmail(input: { email: string; code: string; appUrl: string; idempotencyKey: string }): Promise<OutgoingEmail> {
  const element = <AccountCode code={input.code} logoUrl={mailAssets(input.appUrl).wordmarkUrl} fontUrl={mailAssets(input.appUrl).fontUrl} brand={BRAND.name} />;
  return {
    to: input.email,
    subject: accountCodeSubject(BRAND.name, input.code),
    html: await render(element),
    text: await render(element, { plainText: true }),
    headers: {},
    idempotencyKey: input.idempotencyKey,
  };
}
